from math import gcd, sqrt
modul = 998244353

def modiFun(a, b, p):
	a %= p
	b %= p
	if b == 1:
		return 0
	(count, t, g) = (0, 1, gcd(a, p))
	while g != 1:
		if b % g:
			return -1
		p = p // g
		b = b // g
		t = int(int(int(t * a) // g) % p)
		count += 1
		if b == t:
			return count
		g = gcd(a, p)
	(hash, base, m) = ({}, b, int(sqrt(1.0 * p) + 1))
	for i in range(m):
		hash[base] = i
		base = base * a % p
	(base, temp) = (pow(a, m, p), t)
	for i in range(1, m + 2):
		temp = temp * base % p
		if temp in hash.keys():
			return i * m - hash[temp] + count
	return -1
